        self.module = ptx_load(PTX_SOURCE)

    def forward(self, Q, K, V):
        # Assume Q, K, V are torch tensors on CUDA with dtype=torch.float16
        # Allocate output tensor
        out = torch.empty_like(Q)

        # Extract raw pointers
        q_ptr = Q.data_ptr()
        k_ptr = K.data_ptr()
        v_ptr = V.data_ptr()
        o_ptr = out.data_ptr()

        # Sizes
        B, H, S, D = Q.shape
